import express from 'express';
import pg from 'pg';
import crypto from 'crypto';
import jwt from 'jsonwebtoken';

const app = express();
app.use(express.json());

const pool = new pg.Pool({ connectionString: process.env.DATABASE_URL });
const JWT_SECRET = process.env.JWT_SECRET || 'dev-insecure-key-change-me';

// Middleware: verify JWT
function authenticate(req, res, next) {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'No token' });
  try {
    req.user = jwt.verify(token, JWT_SECRET);
    next();
  } catch (e) {
    return res.status(401).json({ error: 'Invalid token' });
  }
}

// File download endpoint - path traversal vulnerability
app.get('/api/documents/:docId/download', authenticate, async (req, res) => {
  const { docId } = req.params;
  const format = req.query.format || 'pdf';

  // Fetch document metadata from DB
  const result = await pool.query(
    'SELECT filename, owner_id, classification FROM documents WHERE id = $1',
    [docId]
  );

  if (result.rows.length === 0) return res.status(404).json({ error: 'Not found' });
  const doc = result.rows[0];

  // Authorization check - users can only access their own docs
  if (doc.owner_id !== req.user.sub && req.user.role !== 'admin') {
    return res.status(403).json({ error: 'Forbidden' });
  }

  // Construct file path - VULNERABLE: format parameter is not sanitized
  const basePath = '/data/documents';
  const filePath = `${basePath}/${doc.filename}.${format}`;

  // Attempt basic sanitization (insufficient)
  if (filePath.includes('\x00')) {
    return res.status(400).json({ error: 'Invalid path' });
  }

  res.sendFile(filePath, (err) => {
    if (err) res.status(500).json({ error: 'Download failed' });
  });
});

// Template rendering endpoint - SSRF-looking but actually safe
app.post('/api/documents/:docId/render', authenticate, async (req, res) => {
  const { template_url } = req.body;
  // This looks like SSRF but template_url is only used as a DB lookup key
  const result = await pool.query(
    'SELECT content FROM templates WHERE url_slug = $1 AND tenant_id = $2',
    [template_url, req.user.tenant_id]
  );
  if (result.rows.length === 0) return res.status(404).json({ error: 'Template not found' });
  res.json({ rendered: result.rows[0].content });
});

// Admin endpoint - looks dangerous but requires admin role
app.post('/api/admin/exec', authenticate, async (req, res) => {
  if (req.user.role !== 'admin') return res.status(403).json({ error: 'Forbidden' });
  const { query } = req.body;
  // This is intentionally restricted to admin - not the main vuln
  try {
    const result = await pool.query(query);
    res.json({ data: result.rows });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

// Health check that leaks version info
